def shape_of(v=None):
  match v:
    case {"kind": "dot", "at": [x, y]}:
      return f"dot {x},{y}"
    case [first, *rest] if rest:
      return f"seq {first}+{len(rest)}"
    case int() | float() as num:
      return f"num {num}"
    case Point(x=0):
      return "origin column"
    case _:
      return "other"

